#!/usr/bin/env python3
"""Pure-stdlib cover-page prepend for report.pdf (no external PDF libraries).

- Parses the classic xref table (with /Prev /XRefStm support) of the input PDF.
- Copies all original objects verbatim (same object numbers).
- Rewrites the /Pages node to prepend a newly generated cover page object.
- Rebuilds the xref table and trailer, writing the merged result to report.pdf.
"""
import datetime
import os
import re
import sys
import zlib

INPUT = "report.pdf"
OUTPUT = "report_with_cover.pdf"

WHITESPACE = b"\x00\t\n\x0c\r"
DELIMS = b"()<>[]{}/%"

# --------------------------------------------------------------------------
# Width tables (Adobe AFM, per 1000 units) for chars 32..126
# --------------------------------------------------------------------------
HELV = [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,
        556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,
        1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,
        667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,
        333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,
        556,556,333,500,278,556,500,722,500,500,500,334,260,334,584]
HELV_BOLD = [278,333,474,556,556,889,722,238,333,333,389,584,278,333,278,278,
             556,556,556,556,556,556,556,556,556,556,333,333,584,584,584,611,
             975,722,722,722,722,667,611,778,722,278,556,722,611,833,722,778,
             667,778,722,667,611,722,667,944,667,667,611,333,278,333,584,556,
             333,556,611,556,611,556,333,611,611,278,278,556,278,889,611,611,
             611,611,389,556,333,611,556,778,556,556,500,389,280,389,584]


def text_width(text, widths, font_size):
    return sum(widths[max(32, min(126, ord(c))) - 32] for c in text) * font_size / 1000.0


def skip_ws_comments(data, i):
    n = len(data)
    while i < n:
        c = data[i:i + 1]
        if c in WHITESPACE:
            i += 1
        elif c == b"%":
            j = data.find(b"\n", i)
            i = n if j == -1 else j + 1
        else:
            break
    return i


def tokenize(data, i):
    i = skip_ws_comments(data, i)
    if i >= len(data):
        return (None, i, "eof")
    c = data[i:i + 1]
    if c == b"<<":
        return ("<<", i + 2, "dict_open")
    if c == b">>":
        return (">>", i + 2, "dict_close")
    if c == b"[":
        return ("[", i + 1, "array_open")
    if c == b"]":
        return ("]", i + 1, "array_close")
    if c == b"/":
        j = i + 1
        while j < len(data) and data[j:j + 1] not in WHITESPACE and data[j:j + 1] not in DELIMS:
            j += 1
        return (data[i:j], j, "name")
    if c == b"(":
        depth, j = 1, i + 1
        while j < len(data) and depth:
            ch = data[j:j + 1]
            if ch == b"\\":
                j += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
            j += 1
        return (data[i:j], j, "str")
    if c == b"<":
        j = data.find(b">", i + 1)
        if j == -1:
            j = len(data)
        return (data[i:j + 1], j + 1, "str_hex")
    if c in b"+-." or c in b"0123456789":
        j = i + 1
        while j < len(data) and data[j:j + 1] in b"0123456789.+-":
            j += 1
        return (data[i:j], j, "num")
    j = i
    while j < len(data) and data[j:j + 1] not in WHITESPACE and data[j:j + 1] not in DELIMS:
        j += 1
    return (data[i:j], j, "kw")


def parse_value(data, i):
    tok, i, kind = tokenize(data, i)
    if kind == "eof":
        return (None, i)
    if kind == "num":
        # Possible indirect reference: num num R
        tok2, i2, k2 = tokenize(data, i)
        if k2 == "num":
            tok3, i3, k3 = tokenize(data, i2)
            if k3 == "kw" and tok3 == b"R":
                return (("ref", int(tok), int(tok2)), i3)
        val = int(tok) if b"." not in tok else float(tok)
        return (("num", val), i)
    if kind == "name":
        return (("name", tok), i)
    if kind in ("str", "str_hex"):
        return (("str", tok), i)
    if kind == "array_open":
        items = []
        while True:
            tok, j, k = tokenize(data, i)
            if k == "eof" or (k == "array_close" and tok == b"]"):
                i = j
                break
            node, i = parse_value(data, i)
            items.append(node)
        return (("array", items), i)
    if kind == "dict_open":
        pairs = []
        while True:
            tok, j, k = tokenize(data, i)
            if k == "eof" or (k == "dict_close" and tok == b">>"):
                i = j
                break
            if k != "name":
                raise ValueError(f"expected dict key, got {tok!r}")
            key = ("name", tok)
            val, i = parse_value(data, i)
            pairs.append((key, val))
        return (("dict", pairs), i)
    return (("kw", tok), i)


def ser(node):
    kind = node[0]
    if kind == "name":
        return node[1].decode("latin-1")
    if kind == "num":
        v = node[1]
        return str(int(v)) if isinstance(v, int) or v == int(v) else f"{v:.4f}"
    if kind == "str":
        return node[1].decode("latin-1")
    if kind == "ref":
        return f"{node[1]} {node[2]} R"
    if kind == "kw":
        return node[1].decode("latin-1")
    if kind == "array":
        return "[ " + " ".join(ser(x) for x in node[1]) + " ]"
    if kind == "dict":
        return "<< " + " ".join(ser(k) + " " + ser(v) for k, v in node[1]) + " >>"
    return ""


def dict_get(dnode, key):
    for k, v in dnode[1]:
        if k[1] == key:
            return v
    return None


def ref_num(node):
    return node[1] if node[0] == "ref" else None


def parse_object_raw(raw):
    """raw must begin with 'N G obj'. Returns (objnum, gen, value_node, is_stream)."""
    m = re.match(rb"\s*(\d+)\s+(\d+)\s+obj\b", raw)
    if not m:
        raise ValueError(f"not an object: {raw[:40]!r}")
    objnum, gen = int(m.group(1)), int(m.group(2))
    node, i = parse_value(raw, m.end())
    tok, i, kind = tokenize(raw, i)
    is_stream = kind == "kw" and tok == b"stream"
    return objnum, gen, node, is_stream


def parse_classic_xref(data, off):
    if data[off:off + 4] != b"xref":
        raise ValueError(f"expected 'xref' at {off}")
    i = off + 4
    entries = {}
    trailer = None
    while True:
        i = skip_ws_comments(data, i)
        m = re.match(rb"(\d+)\s+(\d+)", data[i:])
        if not m:
            break
        start, count = int(m.group(1)), int(m.group(2))
        i += m.end()
        for k in range(count):
            line = data[i:i + 20]
            o = int(line[0:10])
            g = int(line[11:16])
            t = line[17:18]
            if t not in (b"n", b"f"):
                # tolerate slightly different spacing
                mm = re.search(rb"\s([nf])\s", line)
                t = mm.group(1) if mm else b"n"
            entries[start + k] = (t, o, g)
            i += 20
        j = skip_ws_comments(data, i)
        if data[j:j + 7] == b"trailer":
            trailer, _ = parse_value(data, j + 7)
            i = j + 7
            break
    return entries, trailer


def inflate(raw, filters):
    flt = filters
    if isinstance(flt, str):
        flt = flt.split("/")[1] if flt.startswith("/") else flt
    if flt in (None, [], "/FlateDecode", "FlateDecode"):
        return zlib.decompress(raw)
    raise ValueError(f"unsupported stream filter: {flt}")


def parse_xref_stream(data, off):
    """Parse an xref stream object at off. Returns (entries, trailer_node)."""
    end = data.find(b"endstream", off)
    if end == -1:
        raise ValueError("xref stream: no endstream")
    endobj = data.find(b"endobj", end)
    raw = data[off:endobj if endobj != -1 else end + 10]
    objnum, gen, node, _ = parse_object_raw(raw)
    if node[0] != "dict":
        raise ValueError("xref stream: not a dict")
    length_node = dict_get(node, "/Length")
    if length_node is None or length_node[0] != "num":
        raise ValueError("xref stream: /Length must be a direct number")
    length = int(length_node[1])
    i = raw.find(b"stream") + 6
    if raw[i:i + 2] == b"\r\n":
        i += 2
    elif raw[i:i + 1] in (b"\n", b"\r"):
        i += 1
    sdata = raw[i:i + length]
    filt_node = dict_get(node, "/Filter")
    filters = []
    if filt_node is not None:
        if filt_node[0] == "name":
            filters.append(filt_node[1])
        elif filt_node[0] == "array":
            filters = [x[1] for x in filt_node[1]]
    if filters:
        sdata = inflate(sdata, filters[0])
    w_node = dict_get(node, "/W")
    idx_node = dict_get(node, "/Index")
    w = [int(x[1]) for x in w_node[1]]
    index = [int(x[1]) for x in idx_node[1]] if idx_node is not None else [0, len(w) and 0]
    if idx_node is None:
        index = [0]
        # count derived from data length
        entry_len = sum(w)
        index.append(len(sdata) // entry_len)
    entries = {}
    pos = 0
    for i in range(0, len(index), 2):
        first, count = index[i], index[i + 1]
        for k in range(count):
            entry_len = sum(w)
            f1 = int.from_bytes(sdata[pos:pos + w[0]], "big") if w[0] else 0
            f2 = int.from_bytes(sdata[pos + w[0]:pos + w[0] + w[1]], "big") if w[1] else 0
            f3 = int.from_bytes(sdata[pos + w[0] + w[1]:pos + entry_len], "big") if w[2] else 0
            pos += entry_len
            if f1 == 0:
                entries[first + k] = (b"f", 0, 65535)
            elif f1 == 1:
                entries[first + k] = (b"n", f2, f3)
            elif f1 == 2:
                entries[first + k] = (b"o", f2, f3)
    return entries, node


def get_all_entries(data, startxref):
    """Follow /Prev and /XRefStm; return (merged_entries, latest_trailer)."""
    sections = []  # (entries, trailer) ordered from latest to earliest
    off = startxref
    while off is not None:
        if data[off:off + 4] == b"xref":
            entries, trailer = parse_classic_xref(data, off)
            xstm = dict_get(trailer, "/XRefStm")
            if xstm is not None:
                xstm_off = int(xstm[1])
                x_entries, x_trailer = parse_xref_stream(data, xstm_off)
                merged = dict(entries)
                merged.update(x_entries)
                entries = merged
        else:
            entries, trailer = parse_xref_stream(data, off)
        sections.append((entries, trailer))
        prev = dict_get(trailer, "/Prev")
        off = int(prev[1]) if prev is not None else None
    merged = {}
    for entries, _trailer in reversed(sections):
        merged.update(entries)
    return merged, sections[0][1]


def extract_objstm_objects(data, entries, objstm_num):
    """Return dict objnum -> raw bytes for objects inside the given object stream."""
    t, off, gen = entries[objstm_num]
    if t != b"n":
        raise ValueError("objstm not at regular offset")
    end = data.find(b"endstream", off)
    endobj = data.find(b"endobj", end)
    raw = data[off:endobj if endobj != -1 else end + 10]
    _, _, node, _ = parse_object_raw(raw)
    n_node = dict_get(node, "/N")
    first_node = dict_get(node, "/First")
    filt_node = dict_get(node, "/Filter")
    length_node = dict_get(node, "/Length")
    length = int(length_node[1])
    i = raw.find(b"stream") + 6
    if raw[i:i + 2] == b"\r\n":
        i += 2
    elif raw[i:i + 1] in (b"\n", b"\r"):
        i += 1
    sdata = raw[i:i + length]
    if filt_node is not None:
        flt = filt_node[1] if filt_node[0] == "name" else filt_node[1][0][1]
        sdata = inflate(sdata, flt)
    n = int(n_node[1])
    first = int(first_node[1])
    header = sdata[:first]
    nums = re.findall(rb"(\d+)\s+(\d+)", header)
    result = {}
    for idx in range(n):
        objnum = int(nums[idx][0])
        gen = int(nums[idx][1])
        o1 = first + int(nums[idx + n][1])
        o2 = first + int(nums[idx + n + 1][1]) if idx + n + 1 < len(nums) else len(sdata)
        content = sdata[o1:o2].rstrip(b"\r\n")
        result[objnum] = f"{objnum} {gen} obj\n".encode() + content + b"\nendobj\n"
    return result


def esc_literal(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def fmt_num(x):
    s = f"{x:.2f}"
    return s.rstrip("0").rstrip(".") if "." in s else s


# --------------------------------------------------------------------------
def main():
    if not os.path.exists(INPUT):
        print(f"ERROR: {INPUT} not found", file=sys.stderr)
        sys.exit(1)
    data = open(INPUT, "rb").read()

    m = re.search(rb"startxref\s+(\d+)\s*%%EOF", data)
    if not m:
        print("ERROR: no startxref found", file=sys.stderr)
        sys.exit(1)
    startxref = int(m.group(1))
    entries, trailer = get_all_entries(data, startxref)

    # Root / Pages
    root_node = dict_get(trailer, "/Root")
    root_num = ref_num(root_node)
    info_num = ref_num(dict_get(trailer, "/Info"))

    raw_by_num = {}
    objstm_nums = set()
    for num, (t, o, g) in entries.items():
        if t == b"o":
            objstm_nums.add(o)
        elif t == b"n" and num != 0:
            raw_by_num[num] = (o, g)

    # Extract objects inside object streams
    for osn in sorted(objstm_nums):
        extracted = extract_objstm_objects(data, entries, osn)
        for num, rawb in extracted.items():
            raw_by_num[num] = (rawb, 0)
        raw_by_num.pop(osn, None)  # skip the container itself

    # Determine object raw byte ranges via consecutive offsets
    boundaries = sorted(set([o for o, _g in raw_by_num.values()] + [startxref]))
    raw_map = {}  # objnum -> bytes
    skip_objs = set()  # xref stream objects (type /XRef), already handled containers
    for num, (o, g) in raw_by_num.items():
        nxt = min([b for b in boundaries if b > o], default=startxref)
        chunk = data[o:nxt]
        mm = re.match(rb"\s*(\d+)\s+(\d+)\s+obj\b", chunk)
        if not mm:
            # search nearby for the object header
            j = data.find((f"{num} {g} obj").encode(), o, o + 512)
            if j == -1:
                raise ValueError(f"cannot locate object {num}")
            chunk = data[j:nxt]
            mm = re.match(rb"\s*(\d+)\s+(\d+)\s+obj\b", chunk)
        onum, ogen = int(mm.group(1)), int(mm.group(2))
        raw_map[onum] = chunk
        skip_objs.add(onum)

    # Parse catalog/pages/page/fonts to build the cover
    cat_raw = raw_map.get(root_num)
    if not cat_raw:
        raise ValueError("catalog object missing")
    cat_node = parse_object_raw(cat_raw)[2]
    pages_num = ref_num(dict_get(cat_node, "/Pages"))
    pages_raw = raw_map.get(pages_num)
    if not pages_raw:
        raise ValueError("pages object missing")
    pages_node = parse_object_raw(pages_raw)[2]
    kids_node = dict_get(pages_node, "/Kids")
    count_node = dict_get(pages_node, "/Count")
    kids = kids_node[1] if kids_node is not None else []
    old_count = int(count_node[1]) if count_node is not None else len(kids)

    first_page_num = ref_num(kids[0]) if kids else None
    mediabox = None
    page_node = None
    if first_page_num:
        page_node = parse_object_raw(raw_map[first_page_num])[2]
        mb = dict_get(page_node, "/MediaBox")
        if mb is None:
            mb = dict_get(pages_node, "/MediaBox")
        if mb is not None:
            mediabox = [float(x[1]) for x in mb[1]]
    if not mediabox:
        mediabox = [0.0, 0.0, 612.0, 792.0]
    W, H = mediabox[2] - mediabox[0], mediabox[3] - mediabox[1]

    # Fonts for the cover: reuse fonts from the first page's resources
    reg_ref = bold_ref = None
    if page_node is not None:
        res = dict_get(page_node, "/Resources")
        if res is not None and res[0] == "dict":
            fonts = dict_get(res, "/Font")
            if fonts is not None and fonts[0] == "dict":
                refs = []
                for k, v in fonts[1]:
                    if v[0] == "ref":
                        refs.append((k[1], v[1]))
                for _name, fnum in refs:
                    fraw = raw_map.get(fnum)
                    if fraw:
                        fnode = parse_object_raw(fraw)[2]
                        bf = dict_get(fnode, "/BaseFont")
                        if bf is not None and b"Bold" in bf[1].upper():
                            bold_ref = (b"/F2", fnum)
                        elif reg_ref is None:
                            reg_ref = (b"/F1", fnum)
                if reg_ref is None and refs:
                    reg_ref = (b"/F1", refs[0][1])
                if bold_ref is None and refs:
                    bold_ref = (b"/F2", refs[0][1])
    if reg_ref is None or bold_ref is None:
        raise ValueError("could not determine fonts for cover page")

    # Build cover content stream
    title = "Annual Financial Report"
    today = datetime.date.today().strftime("%B %d, %Y")
    t_fs, d_fs = 28.0, 16.0
    tw = text_width(title, HELV_BOLD, t_fs)
    dw = text_width(today, HELV, d_fs)
    cx = W / 2.0
    title_x = cx - tw / 2.0
    title_y = H * 0.55
    rule_y = title_y - 14.0
    rule_x1 = cx - tw / 2.0 - 10.0
    rule_x2 = cx + tw / 2.0 + 10.0
    date_x = cx - dw / 2.0
    date_y = rule_y - 34.0
    content = (
        b"q\n"
        b"BT\n/F2 " + str(t_fs).encode() + b" Tf\n"
        b"1 0 0 1 " + fmt_num(title_x).encode() + b" " + fmt_num(title_y).encode() + b" Tm\n"
        b"(" + esc_literal(title).encode("latin-1") + b") Tj\nET\n"
        b"2 J 1.5 w\n"
        + fmt_num(rule_x1).encode() + b" " + fmt_num(rule_y).encode() + b" m "
        + fmt_num(rule_x2).encode() + b" " + fmt_num(rule_y).encode() + b" l S\n"
        b"BT\n/F1 " + str(d_fs).encode() + b" Tf\n"
        b"1 0 0 1 " + fmt_num(date_x).encode() + b" " + fmt_num(date_y).encode() + b" Tm\n"
        b"(" + esc_literal(today).encode("latin-1") + b") Tj\nET\n"
        b"Q\n"
    )

    max_num = max([num for num in entries if num != 0] + [0])
    cover_page_num = max_num + 1
    cover_contents_num = max_num + 2

    mb_str = "[ " + " ".join(fmt_num(x) for x in mediabox) + " ]"
    cover_page_raw = (
        f"{cover_page_num} 0 obj\n<< /Type /Page /Parent {pages_num} 0 R "
        f"/MediaBox {mb_str} /Resources << /Font << {reg_ref[0].decode()} {reg_ref[1]} 0 R "
        f"{bold_ref[0].decode()} {bold_ref[1]} 0 R >> /ProcSet [ /PDF /Text ] >> "
        f"/Contents {cover_contents_num} 0 R >>\nendobj\n"
    ).encode()
    cover_contents_raw = (
        f"{cover_contents_num} 0 obj\n<< /Length {len(content)} >>\nstream\n".encode()
        + content + b"endstream\nendobj\n"
    )

    # Rewrite the /Pages node with the cover prepended
    new_kids = [("ref", cover_page_num, 0)] + kids
    new_count = old_count + 1
    new_pairs = []
    replaced_kids = replaced_count = False
    for k, v in pages_node[1]:
        if k[1] == "/Kids" and not replaced_kids:
            new_pairs.append((k, ("array", new_kids)))
            replaced_kids = True
        elif k[1] == "/Count" and not replaced_count:
            new_pairs.append((k, ("num", new_count)))
            replaced_count = True
        else:
            new_pairs.append((k, v))
    if not replaced_kids:
        new_pairs.append((("name", b"/Kids"), ("array", new_kids)))
    if not replaced_count:
        new_pairs.append((("name", b"/Count"), ("num", new_count)))
    pages_new_raw = (f"{pages_num} 0 obj\n" + ser(("dict", new_pairs)) + "\nendobj\n").encode()

    # ---- Assemble output ----
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = {}
    ordered = sorted(set(raw_map.keys()) | {pages_num} | {cover_page_num, cover_contents_num})
    for num in ordered:
        if num in skip_objs:
            continue  # drop original xref streams / objstm containers
        if num == pages_num:
            rawb = pages_new_raw
        elif num == cover_page_num:
            rawb = cover_page_raw
        elif num == cover_contents_num:
            rawb = cover_contents_raw
        else:
            rawb = raw_map[num]
        offsets[num] = len(out)
        out += rawb
        if not rawb.endswith(b"\n"):
            out += b"\n"

    size = max(offsets) + 1
    xref_off = len(out)
    out += b"xref\n"
    out += f"0 {size}\n".encode()
    for i in range(size):
        if i in offsets:
            out += f"{offsets[i]:010d} 00000 n \n".encode()
        else:
            gen = 65535 if i == 0 else 0
            out += f"0000000000 {gen:05d} f \n".encode()
    trailer_pairs = []
    if root_node is not None:
        trailer_pairs.append((("name", b"/Root"), root_node))
    if info_num is not None:
        trailer_pairs.append((("name", b"/Info"), ("ref", info_num, 0)))
    id_node = dict_get(trailer, "/ID")
    if id_node is not None:
        trailer_pairs.append((("name", b"/ID"), id_node))
    trailer_pairs.append((("name", b"/Size"), ("num", size)))
    out += b"trailer\n" + ser(("dict", trailer_pairs)).encode() + b"\n"
    out += b"startxref\n" + str(xref_off).encode() + b"\n%%EOF\n"

    with open(OUTPUT, "wb") as fh:
        fh.write(bytes(out))

    # ---- Validation ----
    verify(OUTPUT, pages_num, cover_page_num, cover_contents_num, old_count + 1)

    os.replace(OUTPUT, INPUT)
    print(f"Cover page added to {INPUT}")
    print(f"  Title: {title}")
    print(f"  Date:  {today}")
    print(f"  Page size: {fmt_num(W)} x {fmt_num(H)}")
    print(f"  Pages: {old_count} -> {old_count + 1}")
    print(f"  New objects: {cover_page_num}, {cover_contents_num}; total size {size}")


def verify(path, pages_num, cover_page_num, cover_contents_num, expected_count):
    data = open(path, "rb").read()
    if not data.startswith(b"%PDF-"):
        raise ValueError("verify: bad header")
    m = re.search(rb"startxref\s+(\d+)\s*%%EOF", data)
    if not m:
        raise ValueError("verify: no startxref")
    entries, trailer = get_all_entries(data, int(m.group(1)))
    root = ref_num(dict_get(trailer, "/Root"))
    cat = parse_object_raw(data[entries[root][1]:]).__class__  # placeholder
    # simpler: re-run parse of catalog and pages
    cat_raw = slice_obj(data, entries, root)
    cat_node = parse_object_raw(cat_raw)[2]
    pnum = ref_num(dict_get(cat_node, "/Pages"))
    if pnum != pages_num:
        raise ValueError("verify: pages mismatch")
    p_raw = slice_obj(data, entries, pnum)
    p_node = parse_object_raw(p_raw)[2]
    kids = dict_get(p_node, "/Kids")
    cnt = dict_get(p_node, "/Count")
    if int(cnt[1]) != expected_count or len(kids[1]) != expected_count:
        raise ValueError("verify: kids/count mismatch")
    if ref_num(kids[1][0]) != cover_page_num:
        raise ValueError("verify: cover not first kid")
    cover_raw = slice_obj(data, entries, cover_page_num)
    c_node = parse_object_raw(cover_raw)[2]
    if dict_get(c_node, "/Type")[1] != b"/Page":
        raise ValueError("verify: cover not a Page")
    cc_num = ref_num(dict_get(c_node, "/Contents"))
    if cc_num != cover_contents_num:
        raise ValueError("verify: cover contents mismatch")
    cc_raw = slice_obj(data, entries, cc_num)
    cc = parse_object_raw(cc_raw)
    if not cc[3]:
        raise ValueError("verify: contents not a stream")
    print("Validation passed: header, xref, catalog, pages, cover page, contents stream")


def slice_obj(data, entries, num):
    t, o, g = entries[num]
    if t != b"n":
        raise ValueError(f"verify: object {num} not regular")
    nxt = min([e[1] for e in entries.values() if e[0] == b"n" and e[1] > o] + [len(data)])
    return data[o:nxt]


